"""Layer 15 MLP down_proj, component 6099: a weak, diffuse signal, described only roughly.

What the component is: a rank-one piece of the MLP down projection. It reads mainly
MLP hidden unit 6099 of layer 15 and writes a fixed direction into the residual
stream, scaled by its activation. When the activation is negative, that direction
pushes the next-token prediction toward an opening bracket "(" or "[", which is what
follows a name or term that is often followed by an abbreviation or aside. When it is
positive, it pushes toward code-like tokens such as "$".

What the program predicts: the activation's typical value for each kind of token,
from a few word-level rules fitted by least squares on training rows:
  - first token of a document: 0 (the component is silent there);
  - second token of a document: about +0.33;
  - otherwise a base of about -0.09, moved by the current token and the previous one:
      * a capitalised word continuing a capitalised name:  -0.23
      * a closing bracket:                                  -0.17
      * a word-piece continuing a word (no leading space):  -0.12
      * a digit:                                            -0.04
      * a content word (leading space, not a function word): -0.03
      * a function word (the, of, a, ...):                  +0.11
      * a comma, full stop, colon or semicolon:             +0.08

This explains only about 1 percent of the activation's variance. Most of the variance
comes from token-level detail that these word classes do not capture.

Documents are told apart by their document label; a new label restarts the count.
"""
import re

READS = ()

FUNCTION_WORDS = {
    "the", "of", "a", "an", "and", "or", "to", "in", "on", "for", "with", "by",
    "from", "as", "at", "is", "are", "was", "were", "be", "been", "that", "this",
    "which", "it", "its", "he", "she", "they", "we", "his", "her", "their",
}


def _is_title_word(s):
    return re.fullmatch(r"\s*[A-Z][a-z]+", s) is not None


def _is_closer(s):
    return re.fullmatch(r"\s*[\)\]\}]+.*", s) is not None


def _is_function_word(s):
    return s[:1] == " " and s.strip().lower() in FUNCTION_WORDS


def _is_content_word(s):
    return s[:1] == " " and re.fullmatch(r"\s*[A-Za-z]+", s) is not None and not _is_function_word(s)


def _is_subword(s):
    return re.fullmatch(r"[a-z]+", s) is not None


def _is_digit(s):
    return re.fullmatch(r"\s*\d+", s) is not None


def _is_punct(s):
    return re.fullmatch(r"\s*[.,;:]+\s*", s) is not None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    cur = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        index, prev = 0, ""
    else:
        index, prev = carry[1] + 1, carry[2]
    if index == 0:
        value = 0.0
    elif index == 1:
        value = 0.33
    else:
        value = -0.09
        if _is_title_word(cur) and _is_title_word(prev):
            value -= 0.23
        if _is_closer(cur):
            value -= 0.17
        if _is_subword(cur):
            value -= 0.12
        if _is_digit(cur):
            value -= 0.04
        if _is_content_word(cur):
            value -= 0.03
        if _is_function_word(cur):
            value += 0.11
        if _is_punct(cur):
            value += 0.08
    return (doc, index, cur), value

"""Component p-82af68dd@100000/layers.15.mlp.down_proj:6100 (layer 15 MLP output, rank-one piece).

What it does, in plain terms: the component fires most on the word just before a word naming a
person or an institution. Its output direction promotes person and role nouns (researchers,
managers, developers, authorities), so it leans toward "a person or group comes next". Its
largest activations sit right before "Mr"/"Dr"-style titles, Chinese surnames, nationality or
ethnic adjectives, and words like "Many"/"Those" (e.g. "Business [manager]", "the [court]").
It goes negative on speech verbs ("said", "told", "replied") that introduce a source or quote.

This program is a small set of cue-word rules with fitted weights. It captures only about 1% of
the variance: the activation is mostly context-driven and not explained by the current word alone.
"""
READS = ()

TITLES = {"Mr", "Mrs", "Ms", "Dr", "Sir", "Judge", "Professor", "Lord", "Lady", "Dame", "Rev",
          "Gen", "Sen", "Rep", "Gov", "Capt", "Col", "Lt", "Sgt", "Mayor"}
SURNAMES = set("陈李王林刘张赵杨黄周吴徐孙马朱胡郭何高罗郑梁谢宋唐许韩冯邓曹彭曾萧田董袁潘于蒋蔡余杜叶程苏魏吕丁任沈姚卢姜崔钟谭陆汪范金石廖贾夏韦付方白邹孟熊秦邱江尹薛闫段雷侯龙史陶黎贺顾毛郝龚邵万钱严覃武戴莫孔向汤")
NATIONALITIES = {"British", "French", "Canadian", "European", "Spanish", "Russian", "American",
                 "Chinese", "German", "Italian", "Japanese", "Federal", "Philippine", "English",
                 "Australian", "Indian", "Irish", "Dutch", "Swiss", "Korean", "Mexican", "Brazilian",
                 "African", "Asian", "Jewish", "Christian", "Muslim", "Catholic", "Greek", "Turkish",
                 "Israeli", "Polish", "Scottish", "Welsh", "Vietnamese"}
PEOPLE_WORDS = {"Many", "many", "Those", "those", "Several", "several", "Some", "some", "Few", "few",
                "fellow", "Person", "person", "people", "Other", "other"}
SPEECH_VERBS = {"said", "told", "tells", "tell", "replied", "wrote", "answered", "commanded",
                "says", "say"}


def is_cjk(text):
    return any("一" <= ch <= "鿿" for ch in text)


def is_cyrillic(text):
    return any("Ѐ" <= ch <= "ӿ" for ch in text)


def step(carry, prefix, upstream):
    if prefix.position == 0:  # a document's first token: the component is ~0 there
        return carry, 0.0
    word = prefix.token_strings[-1].strip()
    value = 0.06  # baseline
    if word in TITLES:
        value += 1.9
    elif word in SURNAMES:
        value += 1.1
    elif word in NATIONALITIES:
        value += 1.3
    elif word in PEOPLE_WORDS:
        value += 0.65
    elif word in SPEECH_VERBS:
        value -= 0.25
    elif word == "the":
        value += 0.07
    elif is_cjk(word):
        value += 0.24
    elif is_cyrillic(word):
        value += 0.19
    elif word and all(not ch.isalnum() for ch in word):
        value -= 0.06  # punctuation
    return carry, value

"""Layer 15, MLP hidden unit 6114 (down_proj component 6114).

This component is almost entirely diffuse: most of its variance is small noise that no
simple rule predicts. Its clearest signal is negative spikes in code:
  * print / log calls (print, printf, console, .log, cout): moderately negative;
  * the opening quote of a string literal, strongest when the quote starts a value
    right after '=' or ':' (a config or keyword assignment), and moderately after '(' or ','.
    Quotes that continue a JSON list or object (after '",' or '":') are near zero.
  * test-like identifiers (test, Test, foo): mildly negative.
The first token of each document is exactly 0. Everything else is predicted as 0.
"""
import re

READS = ()

PRINT_CALL = re.compile(r"(print|printf|println|echo|console|\.log|cout)", re.I)
TEST_WORD = re.compile(r"(test|Test|foo)")
QUOTE_OPEN = re.compile(r"""^(\(|=|:|\(\\)?\s?['"]$|^\\"$""")
VALUE_LEADIN = {"=", ":", "==", "':", '":'}
ARG_LEADIN = {"(", ","}
JSON_LEADIN = {'",', '":'}


def step(carry, prefix, upstream):
    if len(prefix.document_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip()
    if PRINT_CALL.search(tok):
        return carry, -1.4
    if QUOTE_OPEN.match(tok) or tok.strip() in ('"', "'"):
        if prev in VALUE_LEADIN:
            return carry, -2.5
        if prev in ARG_LEADIN:
            return carry, -1.2
        if prev in JSON_LEADIN:
            return carry, 0.0
        return carry, -0.6
    if TEST_WORD.search(tok):
        return carry, -0.45
    return carry, 0.0

"""Layer 15 MLP down-projection, component 6115: a token-class model of its activation.

Almost all of this component's activation comes from one MLP hidden unit (unit 6115 of layer
15: 64% of its input direction). What the unit responds to, on training text:

- Most strongly, connectives that give a reason or a degree: " because" and " due" (and the
  token right after "due" or "because", as in "due to"), and Japanese degree phrases such as
  ほど, くらい, ぐらい and ような ("to the extent that", "so much that"). 因为 likewise.
- Weakly positive at clause ends (. 。 ! ？ ." and commas), at " by", " so", " since", and in
  Japanese kana text.
- Negative on clause-opening hedges: " think", " probably", " guess", " hope", " certainly".
- Zero elsewhere.

The program is a fixed table of these classes, each with its mean activation fitted on
training text. It explains only about 2-3% of the activation's variance: a 4-token or
32-token lexical model reaches only about 4%, so most of the variance depends on context
that no list of words captures.
"""

READS = ()

REASON_DEGREE = {
    " because": 2.5,
    "因为": 3.0,
    "ので": 2.0,
    "ため": 2.0,
    "ほど": 5.1,
    "くらい": 5.1,
    "ぐらい": 5.1,
    "ような": 5.1,
    "ように": 5.1,
    "という": 5.1,
    " due": 1.7,
}
WEAK_POSITIVE = {" by": 0.6, " so": 0.6, " since": 0.6}
CLAUSE_END = {".", "。", "!", "！", "?", "？", ".\n", '."', ".”", ",", "，"}
HEDGE = {" think", " probably", " guess", " hope", " certainly", " definitely", " wonder", " imagine", " doubt"}


def is_kana(text):
    return any("぀" <= ch <= "ヿ" for ch in text)


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if prefix.position > 0 else ""
    if tok in REASON_DEGREE:
        value = REASON_DEGREE[tok]
    elif tok in HEDGE:
        value = -0.9
    elif tok in CLAUSE_END:
        value = 0.4
    elif tok in WEAK_POSITIVE:
        value = 0.6
    elif is_kana(tok):
        value = 0.4
    else:
        value = 0.0
    if prev in (" due", " because"):
        value += 1.8  # the word right after "due" or "because", as in "due to"
    return carry, float(value)

"""Amount and unit words: a weak feature of layer 15's MLP, one neuron's output.

Component p-82af68dd@100000/layers.15.mlp.down_proj:6128 reads out largely one hidden unit
of layer 15's MLP (unit 6128), which carries about 60% of its variance. Its activation is
usually small, but it goes strongly negative where the text sets up an amount or a unit:

- amount words: "single", "one", "each", "per", "whole", "half", "a" in "once a year";
- unit nouns: "hours", "minutes", "cups", "dollars", "million";
- and most of all where a number or unit is already on the page: "0 per", "5 hours",
  "pounds per", "of one", "in one".

Comparison and relation words ("than", "more", "between", "over", "different", "number")
push it mildly positive. When it is negative, the component promotes measure words and
quantity continuations in the next-token distribution.

The program reads the newest token and the one before it. Each word group takes the
mean activation measured on training rows; everything else is 0. It captures the sign
and rough size of the amount-word events. It does not capture most of the variance,
which lies in context that no word list reaches.
"""

READS = ()

# Words that set up an amount: quantifiers and distributive words.
AMOUNT_WORDS = {
    "single", "each", "per", "one", "whole", "entire", "half", "full", "few",
    "every", "once", "twice", "only", "just", "two", "three",
}
# Measure, time and money nouns that name the unit of an amount.
UNIT_WORDS = {
    "minute", "minutes", "hour", "hours", "day", "days", "week", "weeks", "month",
    "months", "year", "years", "second", "seconds", "cup", "cups", "ounce", "ounces",
    "pound", "pounds", "mile", "miles", "gram", "grams", "kg", "ml", "liter", "liters",
    "dollar", "dollars", "million", "billion", "percent",
}
ARTICLES = {"a", "an"}
# Words that come before an amount: "of one", "in one", "about a", "for a".
PREPOSITIONS = {
    "in", "of", "for", "with", "on", "into", "within", "about", "just", "at", "by",
    "from", "to", "per", "than", "during", "once", "around", "only",
}
NUMBER_WORDS = {"two", "three", "four", "five", "six", "seven", "eight", "nine", "ten",
                "hundred", "thousand", "million", "billion", "dozen"}
# Words of comparison and relation: mildly positive.
RELATION_WORDS = {
    "than", "more", "between", "over", "after", "different", "number", "total", "many",
    "how",
}


def is_number(word):
    return word.replace(",", "").replace(".", "").isdigit() or word in NUMBER_WORDS


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if word in AMOUNT_WORDS:
        return carry, -1.9 if is_number(prev) else -0.5
    if word in UNIT_WORDS:
        return carry, -1.2 if is_number(prev) else -0.2
    if word in ARTICLES:
        return carry, -0.4 if prev in PREPOSITIONS else -0.2
    if word in RELATION_WORDS:
        return carry, 0.3
    return carry, 0.0

"""Word-class means: predict the component's average activation for the newest
token's word class.

The component is one MLP hidden unit of layer 15 (neuron 6137, about 71% of its
weight). Its output direction, read through the embeddings, favours "its" and
"their" as the next word, so positive activations push toward possessives. But
its activation depends only weakly on the current word: "by" runs higher than
average, while "in", "of" and digits run lower; spaces and punctuation sit near
the average. These class means explain almost none of its variance (about 0.2%
on held-out data). Most of it is context-driven spikes that no word-level rule
we tested captures.
"""

import re
from collections.abc import Mapping

READS: tuple[str, ...] = ()

PREPOSITIONS = set("by to with from of in on into for at as than through".split())
DETERMINERS = set("the a an this that these those its their his her our my your".split())
CONJUNCTIONS = set("and or but which who whom while if so because".split())


def word_class_mean(token: str) -> float:
    word = token.strip()
    if word == "":
        return -0.055
    if word == "by":
        return 0.19
    if word == "with":
        return 0.04
    if word in ("in", "of"):
        return -0.10
    if word in PREPOSITIONS:
        return -0.05
    if word in DETERMINERS:
        return -0.04
    if word in CONJUNCTIONS:
        return -0.05
    if re.fullmatch(r"\d+", word):
        return -0.085
    if re.fullmatch(r"[^\w\s]+", word):
        return -0.056
    return -0.075


def step(carry, prefix, upstream: Mapping):
    return carry, word_class_mean(prefix.token_strings[-1])
